        height: 18px;
        margin: 0;
        border-radius: 50%;
        border: 2px solid rgba(180, 193, 222, 0.65);
        display: grid;
        place-items: center;
        flex: 0 0 auto;
        background: rgba(255, 255, 255, 0.02);
      }

      .radio-option input::before {
        content: "";
        width: 10px;
        height: 10px;
        border-radius: 50%;
        transform: scale(0);
        transition: transform 0.15s ease;
        background: linear-gradient(135deg, var(--accent), var(--accent-2));
